import os
from dataclasses import dataclass

import requests
from langchain_core.tools import tool


@dataclass
class ReplicationNotice:
    job_id: str
    state: str
    webhook_status: int


@tool
def trigger_replication_webhook(bucket: str, webhook_url: str) -> ReplicationNotice:
    base = os.environ["STORAGE_ADMIN_URL"]
    headers = {"Authorization": f"Bearer {os.environ['STORAGE_ADMIN_TOKEN']}"}
    run = requests.post(f"{base}/buckets/{bucket}/replication/run", headers=headers, timeout=30)
    run.raise_for_status()
    job = run.json()
    hook = requests.post(
        webhook_url,
        json={"bucket": bucket, "job_id": job["job_id"], "state": job["state"]},
        timeout=15,
    )
    return ReplicationNotice(job_id=job["job_id"], state=job["state"], webhook_status=hook.status_code)
